# ============================================================
# COMBINE AND COMPUTE TENURE
# ============================================================
all_leaders <- bind_rows(uk, germany, canada, australia, japan) |>
  mutate(
    start = as.Date(start),
    end   = as.Date(end),
    tenure_years = as.numeric(end - start) / 365.25
  )

cat("========== LEADERS BY COUNTRY ==========\n")
all_leaders |>
  group_by(country) |>
  summarise(
    n_leaders = n(),
    mean_tenure = round(mean(tenure_years), 2),
    median_tenure = round(median(tenure_years), 2),
    .groups = "drop"
  ) |>
  arrange(mean_tenure) |>
  print()

# ============================================================
# ROLLING AVERAGE OF LEADERSHIP CHANGES
# ============================================================

# Annual changes per country
changes <- all_leaders |>
  filter(start > as.Date("1945-01-01") | country == "Germany") |>
  mutate(change_year = as.numeric(format(start, "%Y")))

# Germany starts 1949
min_year <- 1946
max_year <- 2026

annual <- expand_grid(
  country = unique(all_leaders$country),
  year = min_year:max_year
) |>
  # Germany only from 1949
  filter(!(country == "Germany" & year < 1949)) |>
  left_join(
    changes |>
      group_by(country, change_year) |>
      summarise(n = n(), .groups = "drop"),
    by = c("country", "year" = "change_year")
  ) |>
  mutate(n = replace_na(n, 0)) |>
  arrange(country, year) |>
  group_by(country) |>
  mutate(rolling = zoo::rollmean(n, k = 5, fill = NA, align = "right")) |>
  ungroup() |>
  filter(!is.na(rolling)) |>
  mutate(country = factor(country,
    levels = c("UK", "Australia", "Japan", "Canada", "Germany")))

# Others average
others_avg <- annual |>
  filter(country != "UK") |>
  group_by(year) |>
  summarise(rolling = mean(rolling, na.rm = TRUE), .groups = "drop") |>
  mutate(country = "Other 4 (mean)")

uk_data <- annual |> filter(country == "UK")

# ============================================================
# STATISTICAL TESTS (on annual counts, full series)
# ============================================================

annual_raw <- expand_grid(
  country = unique(all_leaders$country),
  year = 1950:2026
) |>
  filter(!(country == "Germany" & year < 1950)) |>
  left_join(
    changes |>
      group_by(country, change_year) |>
      summarise(n = n(), .groups = "drop"),
    by = c("country", "year" = "change_year")
  ) |>
  mutate(
    n = replace_na(n, 0),
    uk = as.integer(country == "UK"),
    t = year - 1950
  )

# Test 1: UK vs others overall
m1 <- lm(n ~ uk, data = annual_raw)
cat("\n========== TEST 1: UK vs OTHERS (level) ==========\n")
cat(sprintf("UK mean: %.3f changes/yr\n", mean(annual_raw$n[annual_raw$uk == 1])))
cat(sprintf("Others mean: %.3f changes/yr\n", mean(annual_raw$n[annual_raw$uk == 0])))
cat(sprintf("Difference: %.3f, p = %.4f\n",
            coef(m1)["uk"], summary(m1)$coefficients["uk", "Pr(>|t|)"]))

# Test 2: Divergence over time
m2 <- lm(n ~ uk * t, data = annual_raw)
cat("\n========== TEST 2: UK DIVERGENCE OVER TIME ==========\n")
print(round(coef(summary(m2)), 4))
cat(sprintf("\nUK*time interaction: %.4f (p = %.4f)\n",
            coef(m2)["uk:t"], summary(m2)$coefficients["uk:t", "Pr(>|t|)"]))

# Permutation test (linear)
set.seed(42)
n_perm <- 10000
obs_interact <- coef(m2)["uk:t"]
perm_interact <- replicate(n_perm, {
  d_perm <- annual_raw
  d_perm$uk <- sample(d_perm$uk)
  coef(lm(n ~ uk * t, data = d_perm))["uk:t"]
})
perm_p <- mean(abs(perm_interact) >= abs(obs_interact))
cat(sprintf("Permutation p (two-sided, %d perms): %.4f\n", n_perm, perm_p))

# Test 3: Quadratic interaction — does UK ACCELERATE relative to others?
annual_raw$t2 <- annual_raw$t^2
m3 <- lm(n ~ uk * (t + t2), data = annual_raw)
cat("\n========== TEST 3: UK ACCELERATION (quadratic interaction) ==========\n")
cat("Model: changes ~ UK + time + time² + UK*time + UK*time²\n")
print(round(coef(summary(m3)), 4))
obs_quad <- coef(m3)["uk:t2"]
cat(sprintf("\nUK*time² interaction: %.6f (p = %.4f)\n",
            obs_quad, summary(m3)$coefficients["uk:t2", "Pr(>|t|)"]))

# Permutation test on quadratic interaction
set.seed(42)
perm_quad <- replicate(n_perm, {
  d_perm <- annual_raw
  d_perm$uk <- sample(d_perm$uk)
  coef(lm(n ~ uk * (t + t2), data = d_perm))["uk:t2"]
})
perm_p_quad <- mean(abs(perm_quad) >= abs(obs_quad))
cat(sprintf("Permutation p (two-sided, %d perms): %.4f\n", n_perm, perm_p_quad))

# Test 4: Piecewise DiD — scan for breakpoint in UK-others divergence
cat("\n========== TEST 4: PIECEWISE DiD (breakpoint scan) ==========\n")

# For each candidate break year, fit:
# n ~ uk + post + uk*post (where post = year >= break)
break_years <- 1970:2020
did_results <- sapply(break_years, function(by) {
  annual_raw$post <- as.integer(annual_raw$year >= by)
  m <- lm(n ~ uk * post, data = annual_raw)
  c(year = by,
    did_coef = coef(m)["uk:post"],
    did_p = summary(m)$coefficients["uk:post", "Pr(>|t|)"])
})
did_df <- as.data.frame(t(did_results))
names(did_df) <- c("year", "did_coef", "did_p")

# Best breakpoint = largest absolute DiD coefficient
best_break <- did_df[which.max(abs(did_df$did_coef)), ]
cat(sprintf("Best breakpoint: %d\n", best_break$year))
cat(sprintf("DiD coefficient: %.4f (UK changes %.4f more per year post-break)\n",
            best_break$did_coef, best_break$did_coef))
cat(sprintf("Parametric p: %.4f\n", best_break$did_p))

# Permutation test on best-break DiD
set.seed(42)
obs_did <- best_break$did_coef
perm_did <- replicate(n_perm, {
  d_perm <- annual_raw
  d_perm$uk <- sample(d_perm$uk)
  d_perm$post <- as.integer(d_perm$year >= best_break$year)
  coef(lm(n ~ uk * post, data = d_perm))["uk:post"]
})
perm_p_did <- mean(abs(perm_did) >= abs(obs_did))
cat(sprintf("Permutation p (two-sided, %d perms): %.4f\n", n_perm, perm_p_did))

# Pre/post means for the best break
pre_uk  <- mean(annual_raw$n[annual_raw$uk == 1 & annual_raw$year < best_break$year])
post_uk <- mean(annual_raw$n[annual_raw$uk == 1 & annual_raw$year >= best_break$year])
pre_oth <- mean(annual_raw$n[annual_raw$uk == 0 & annual_raw$year < best_break$year])
post_oth <- mean(annual_raw$n[annual_raw$uk == 0 & annual_raw$year >= best_break$year])
cat(sprintf("\nPre-%d:  UK = %.3f, Others = %.3f (UK - Others = %.3f)\n",
            best_break$year, pre_uk, pre_oth, pre_uk - pre_oth))
cat(sprintf("Post-%d: UK = %.3f, Others = %.3f (UK - Others = %.3f)\n",
            best_break$year, post_uk, post_oth, post_uk - post_oth))

