# ============================================================
# LOESS-SMOOTHED FIGURE
# ============================================================

# Annual counts for all countries (for smoothing)
annual_all <- expand_grid(
  country = unique(all_leaders$country),
  year = min_year:max_year
) |>
  filter(!(country == "Germany" & year < 1949)) |>
  left_join(
    changes |>
      group_by(country, change_year) |>
      summarise(n = n(), .groups = "drop"),
    by = c("country", "year" = "change_year")
  ) |>
  mutate(
    n = replace_na(n, 0),
    country = factor(country,
      levels = c("UK", "Australia", "Japan", "Canada", "Germany"))
  )

# Others average per year (unsmoothed, then smooth)
others_annual <- annual_all |>
  filter(country != "UK") |>
  group_by(year) |>
  summarise(n = mean(n, na.rm = TRUE), .groups = "drop")

uk_annual <- annual_all |> filter(country == "UK")

# LOESS span — 0.3 gives a good balance of smooth and responsive
loess_span <- 0.3

# Predict smooth curves
uk_loess <- loess(n ~ year, data = uk_annual, span = loess_span)
uk_smooth <- tibble(
  year = uk_annual$year,
  smooth = pmax(predict(uk_loess), 0)  # floor at 0
)

others_loess <- loess(n ~ year, data = others_annual, span = loess_span)
others_smooth <- tibble(
  year = others_annual$year,
  smooth = pmax(predict(others_loess), 0)
)

# Individual country smooths
indiv_smooth <- annual_all |>
  filter(country != "UK") |>
  group_by(country) |>
  group_modify(~ {
    lo <- loess(n ~ year, data = .x, span = loess_span)
    tibble(year = .x$year, smooth = pmax(predict(lo), 0))
  }) |>
  ungroup()

country_lines <- c(
  "UK"        = "solid",
  "Australia" = "dashed",
  "Japan"     = "dotted",
  "Canada"    = "longdash",
  "Germany"   = "dotdash"
)

fig <- ggplot() +
  # Individual country smooths (thin, light grey)
  geom_line(data = indiv_smooth,
            aes(x = year, y = smooth, linetype = country),
            linewidth = 0.4, colour = "#bbbbbb") +
  # Others average smooth (thick grey)
  geom_line(data = others_smooth,
            aes(x = year, y = smooth),
            linewidth = 1.2, colour = "#888888") +
  # UK smooth (thick black)
  geom_line(data = uk_smooth,
            aes(x = year, y = smooth),
            linewidth = 1.2, colour = "#000000") +
  # Labels — UK and Others (bold lines)
  annotate("text", x = 2027, y = tail(uk_smooth$smooth, 1),
           label = "UK", fontface = "bold", size = 3.5, hjust = 0) +
  annotate("text", x = 2027, y = tail(others_smooth$smooth, 1),
           label = "Others", colour = "#888888", fontface = "bold",
           size = 3.5, hjust = 0) +
  # Labels — individual countries (at end of each line)
  annotate("text", x = 2027,
           y = tail(indiv_smooth$smooth[indiv_smooth$country == "Japan"], 1),
           label = "Japan", colour = "#bbbbbb", size = 2.8, hjust = 0) +
  annotate("text", x = 2027,
           y = tail(indiv_smooth$smooth[indiv_smooth$country == "Australia"], 1),
           label = "Australia", colour = "#bbbbbb", size = 2.8, hjust = 0) +
  annotate("text", x = 2027,
           y = tail(indiv_smooth$smooth[indiv_smooth$country == "Canada"], 1),
           label = "Canada", colour = "#bbbbbb", size = 2.8, hjust = 0) +
  annotate("text", x = 2027,
           y = tail(indiv_smooth$smooth[indiv_smooth$country == "Germany"], 1),
           label = "Germany", colour = "#bbbbbb", size = 2.8, hjust = 0) +
  scale_linetype_manual(values = country_lines, name = NULL) +
  scale_x_continuous(breaks = seq(1950, 2025, 10),
                     expand = expansion(add = c(0.5, 4))) +
  scale_y_continuous(limits = c(0, NA), expand = expansion(mult = c(0, 0.1))) +
  labs(x = NULL, y = "Leadership changes per year\n(LOESS-smoothed)") +
  theme_minimal(base_size = 10) +
  theme(
    panel.grid.minor   = element_blank(),
    panel.grid.major.x = element_blank(),
    legend.position    = "none"
  ) +
  plot_annotation(
    title = "Figure 2.5: Leadership turnover in five parliamentary democracies, 1945\u20132026",
    subtitle = paste0(
      "LOESS-smoothed (span = ", loess_span, "). Bold black = UK; bold grey = mean of Germany, Canada, Australia, Japan."
    ),
    caption = "Sources: gov.uk, bundeskanzler.de, kantei.go.jp, pm.gc.ca, Australian Parliament Handbook. Germany from 1949.",
    theme = theme(
# 17 Aug, PJ: "some of the titles are too small typface". Title size was a raw pt value while
# canvases run 6.5-10 in, so the SAME pt looked large on a narrow figure and small on a wide
# one - a 68% spread in apparent size. Titles are now set at ~1.75 pt per inch of canvas
# (this figure is 10.0 in wide, so 17.5 pt), which is the ratio the narrow figures already had.
      plot.title    = element_text(face = "bold", size = 17.5),
      plot.subtitle = element_text(size = 8.5, colour = "grey30", lineheight = 1.2),
      plot.caption  = element_text(size = 7, colour = "grey40")
    )
  )

ggsave("figures/fig_2_5_comparative_tenure.png",
       fig, width = 10, height = 5, dpi = 300)
cat("\nSaved: figures/fig_2_5_comparative_tenure.png\n")

